INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'A change that produces one or more new substances.', 'Chemical change', 'The correct term is: Chemical change.', true),
