('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The evidence of a chemical reaction shown when vinegar reacts with baking soda and bubbles are produced.', 'Gas evolution (gas formation)', 'The correct term is: Gas evolution (gas formation).', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The evidence of a chemical reaction shown when milk forms lumpy solids.', 'Formation of a precipitate', 'The correct term is: Formation of a precipitate.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The evidence shown when quicklime reacts with water and releases heat.', 'Temperature change (heat released)', 'The correct term is: Temperature change (heat released).', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The change that occurs when paper is cut into smaller pieces.', 'Physical change', 'The correct term is: Physical change.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The evidence of a chemical reaction when a yellow solid forms after mixing two clear solutions.', 'Precipitate formation', 'The correct term is: Precipitate formation.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The substances found on the left side of a chemical equation.', 'Reactants', 'The correct term is: Reactants.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The substances formed on the right side of a chemical equation.', 'Products', 'The correct term is: Products.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The meaning of the symbol (aq) in a chemical equation.', 'Aqueous (dissolved in water)', 'The correct term is: Aqueous (dissolved in water).', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The meaning of the symbol Δ written above the reaction arrow.', 'Heat is supplied', 'The correct term is: Heat is supplied.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The meaning of the downward arrow (↓) in a chemical equation.', 'Precipitate (solid formed)', 'The correct term is: Precipitate (solid formed).', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The meaning of the plus sign (+) between substances in a chemical equation.', 'Reacts with / mixed with', 'The correct term is: Reacts with / mixed with.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The reaction type represented by A + B → AB.', 'Combination (Synthesis) reaction', 'The correct term is: Combination (Synthesis) reaction.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The reaction type shown by 2Na + Cl₂ → 2NaCl.', 'Combination (Synthesis) reaction', 'The correct term is: Combination (Synthesis) reaction.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The reaction type represented by CaCO₃ → CaO + CO₂.', 'Decomposition reaction', 'The correct term is: Decomposition reaction.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The general equation for a decomposition reaction.', 'AB → A + B', 'The correct term is: AB → A + B.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The reaction in which one element replaces another element in a compound.', 'Single displacement reaction', 'The correct term is: Single displacement reaction.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The reaction type represented by AgNO₃ + NaCl → AgCl + NaNO₃.', 'Double displacement reaction', 'The correct term is: Double displacement reaction.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The gas that is always required for combustion reactions.', 'Oxygen (O₂)', 'The correct term is: Oxygen (O₂).', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The two products always formed during the complete combustion of a hydrocarbon.', 'Carbon dioxide (CO₂) and water (H₂O)', 'The correct term is: Carbon dioxide (CO₂) and water (H₂O).', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The reaction represented by HBr + NaOH → NaBr + H₂O.', 'Neutralization (Acid–Base reaction)', 'The correct term is: Neutralization (Acid–Base reaction).', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The special type of double displacement reaction involving an acid and a base.', 'Neutralization', 'The correct term is: Neutralization.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The type of change represented by melting wax.', 'Physical change', 'The correct term is: Physical change.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The process represented by dissolving salt in water.', 'Physical change', 'The correct term is: Physical change.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'In the equation Mg + O₂ → MgO, the substance MgO is called the ________.', 'Product', 'The correct term is: Product.', true),
('b0000000-0000-0000-0000-000000000101', 3, 'post_test', 'The meaning of the reaction arrow (→) in a chemical equation.', 'Yields / Produces', 'The correct term is: Yields / Produces.', true);
