('b0000000-0000-0000-0000-000000000103', 3, 'post_test', 'The color of phenolphthalein in a basic solution.', 'Bright pink', 'The correct term is: Bright pink.', true),
('b0000000-0000-0000-0000-000000000103', 3, 'post_test', 'The ion released by acids in water according to the Arrhenius definition.', 'H⁺ (Hydrogen ion) / H₃O⁺', 'The correct term is: H⁺ (Hydrogen ion) / H₃O⁺.', true),
