('b0000000-0000-0000-0000-000000000103', 3, 'post_test', 'The chemical formula of common table salt.', 'NaCl', 'The correct term is: NaCl.', true),
('b0000000-0000-0000-0000-000000000103', 3, 'post_test', 'The chemical formula of hydrochloric acid found in the stomach.', 'HCl', 'The correct term is: HCl.', true),
