('b0000000-0000-0000-0000-000000000103', 3, 'post_test', 'The reaction between an acid and a base that produces salt and water.', 'Neutralization', 'The correct term is: Neutralization.', true),
('b0000000-0000-0000-0000-000000000103', 3, 'post_test', 'The type of indicator that changes smell instead of color in acids and bases.', 'Olfactory indicator', 'The correct term is: Olfactory indicator.', true),
('b0000000-0000-0000-0000-000000000103', 3, 'post_test', 'The approximate mouth pH at which tooth enamel begins to dissolve.', 'pH 5.5', 'The correct term is: pH 5.5.', true),
('b0000000-0000-0000-0000-000000000103', 3, 'post_test', 'The salt that forms a basic solution when dissolved in water.', 'Sodium carbonate (Na₂CO₃)', 'The correct term is: Sodium carbonate (Na₂CO₃).', true),
('b0000000-0000-0000-0000-000000000103', 3, 'post_test', 'The salt that forms an acidic solution when dissolved in water.', 'Ammonium chloride (NH₄Cl)', 'The correct term is: Ammonium chloride (NH₄Cl).', true),
('b0000000-0000-0000-0000-000000000103', 3, 'post_test', 'The reason dry hydrogen chloride gas does not affect dry blue litmus paper.', 'No water is present to ionize HCl and produce H⁺ ions', 'The correct term is: No water is present to ionize HCl and produce H⁺ ions.', true),
('b0000000-0000-0000-0000-000000000103', 3, 'post_test', 'The factor by which hydrogen ion concentration changes for every one-unit change in pH.', '10×', 'The correct term is: 10×.', true),
('b0000000-0000-0000-0000-000000000103', 3, 'post_test', 'Arrange the following pH values from strongest acid to strongest base: 2, 6, 7, 9, 12.', '2 → 6 → 7 → 9 → 12', 'The correct term is: 2 → 6 → 7 → 9 → 12.', true),
('b0000000-0000-0000-0000-000000000103', 3, 'post_test', 'The neutral salt produced by the reaction of hydrochloric acid and sodium hydroxide.', 'Sodium chloride (NaCl)', 'The correct term is: Sodium chloride (NaCl).', true),
('b0000000-0000-0000-0000-000000000103', 3, 'post_test', 'The particles that allow acidic and basic solutions to conduct electricity.', 'Mobile ions', 'The correct term is: Mobile ions.', true),
('b0000000-0000-0000-0000-000000000103', 3, 'post_test', 'The safe laboratory practice when diluting concentrated acids.', 'Pour acid slowly into water while stirring', 'The correct term is: Pour acid slowly into water while stirring.', true),
('b0000000-0000-0000-0000-000000000103', 3, 'post_test', 'The gas released when baking soda reacts with an acid.', 'Carbon dioxide (CO₂)', 'The correct term is: Carbon dioxide (CO₂).', true),
('b0000000-0000-0000-0000-000000000103', 3, 'post_test', 'The indicator that remains blue in a basic solution.', 'Blue litmus paper', 'The correct term is: Blue litmus paper.', true),
('b0000000-0000-0000-0000-000000000103', 3, 'post_test', 'The substance released by bases that gives them their basic properties.', 'Hydroxide ion (OH⁻)', 'The correct term is: Hydroxide ion (OH⁻).', true),
('b0000000-0000-0000-0000-000000000103', 3, 'post_test', 'The product formed together with water during a neutralization reaction.', 'Salt', 'The correct term is: Salt.', true);
