INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000104', 3, 'post_test', 'The substances found on the left side of a chemical equation.', 'Reactants', 'The correct term is: Reactants.', true),
('b0000000-0000-0000-0000-000000000104', 3, 'post_test', 'The substances found on the right side of a chemical equation.', 'Products', 'The correct term is: Products.', true),
('b0000000-0000-0000-0000-000000000104', 3, 'post_test', 'The meaning of the symbol (aq) in a chemical equation.', 'Aqueous (dissolved in water)', 'The correct term is: Aqueous (dissolved in water).', true),
('b0000000-0000-0000-0000-000000000104', 3, 'post_test', 'The meaning of the symbol (s) in a chemical equation.', 'Solid', 'The correct term is: Solid.', true),
