('b0000000-0000-0000-0000-000000000104', 3, 'post_test', 'The correct chemical formula for carbon dioxide.', 'CO₂', 'The correct term is: CO₂.', true),
('b0000000-0000-0000-0000-000000000104', 3, 'post_test', 'In the formula CaCl₂, the subscript "2" refers to the number of __________ atoms.', 'Chlorine', 'The correct term is: Chlorine.', true),
('b0000000-0000-0000-0000-000000000104', 3, 'post_test', 'The only numbers that may be changed when balancing a chemical equation.', 'Coefficients', 'The correct term is: Coefficients.', true),
