('b0000000-0000-0000-0000-000000000104', 3, 'post_test', 'The balanced equation among the following: Ca + Cl₂ → CaCl₂. What is its condition?', 'Already balanced', 'The correct term is: Already balanced.', true),
('b0000000-0000-0000-0000-000000000104', 3, 'post_test', 'The total number of hydrogen atoms in 2H₂SO₄.', '4 hydrogen atoms', 'The correct term is: 4 hydrogen atoms.', true),
('b0000000-0000-0000-0000-000000000104', 3, 'post_test', 'The total number of oxygen atoms in 4Al₂O₃.', '12 oxygen atoms', 'The correct term is: 12 oxygen atoms.', true),
('b0000000-0000-0000-0000-000000000104', 3, 'post_test', 'In the equation Mg + 2HCl → MgCl₂ + H₂, how many chlorine atoms are present in the product?', '2 chlorine atoms', 'The correct term is: 2 chlorine atoms.', true),
('b0000000-0000-0000-0000-000000000104', 3, 'post_test', 'The first step in balancing any chemical equation.', 'Count the atoms of each element on both sides', 'The correct term is: Count the atoms of each element on both sides.', true),
('b0000000-0000-0000-0000-000000000104', 3, 'post_test', 'The reason chemical equations must be balanced.', 'To obey the Law of Conservation of Mass', 'The correct term is: To obey the Law of Conservation of Mass.', true),
('b0000000-0000-0000-0000-000000000104', 3, 'post_test', 'If gas escapes from an open container during a reaction, what law still applies?', 'Law of Conservation of Mass', 'The correct term is: Law of Conservation of Mass.', true),
('b0000000-0000-0000-0000-000000000104', 3, 'post_test', 'In the equation N₂ + H₂ → NH₃, the elements that are initially unbalanced are __________.', 'Nitrogen and Hydrogen', 'The correct term is: Nitrogen and Hydrogen.', true),
