('b0000000-0000-0000-0000-000000000104', 3, 'post_test', 'The action that is not allowed when balancing chemical equations.', 'Changing the subscripts', 'The correct term is: Changing the subscripts.', true),
('b0000000-0000-0000-0000-000000000104', 3, 'post_test', 'Balance the equation: __ H₂ + __ O₂ → __ H₂O.', '2, 1, 2', 'The correct term is: 2, 1, 2.', true),
('b0000000-0000-0000-0000-000000000104', 3, 'post_test', 'Balance the equation: __ N₂ + __ H₂ → __ NH₃.', '1, 3, 2', 'The correct term is: 1, 3, 2.', true),
