('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'A reaction that absorbs heat from its surroundings.', 'Endothermic reaction', 'The correct term is: Endothermic reaction.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'The factor increased when a solid reactant is crushed into smaller pieces.', 'Surface area', 'The correct term is: Surface area.', true),
