('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'A substance that slows down a chemical reaction.', 'Inhibitor', 'The correct term is: Inhibitor.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'A common example of an exothermic reaction.', 'Combustion (burning wood)', 'The correct term is: Combustion (burning wood).', true),
