('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'The theory stating that particles must collide with enough energy and proper orientation for a reaction to occur.', 'Collision theory', 'The correct term is: Collision theory.', true),
('b0000000-0000-0000-0000-000000000106', 3, 'post_test', 'The effect of crushing a solid reactant on its reaction rate.', 'Increases the reaction rate', 'The correct term is: Increases the reaction rate.', true),
